examples.template:
MonarchWidget(
    {{title}},
    period: {{period}},
    updatedAt: Date(timeIntervalSinceNow: {{updatedAt|date}}.timeIntervalSince({{now|date}})),
    onViewAll: {},
    menu: {
        Button({{menu.0.label}}) {}
        Button({{menu.1.label}}) {}
        if {{menu.2.separatorBefore}} { Divider() }
        Button({{menu.2.label}}, role: {{menu.2.destructive}} ? .destructive : nil) {}
    },
    content: {
        Text({{body}})
            .monarchTextStyle(.body)
    }
)

